import { column, Schema, Table } from '@powersync/web'

// The device's SQLite copy, as generated by the PowerSync dashboard from the
// deployed Sync Streams. Keep in step with them: a column synced but missing
// here is dropped; one here but not synced stays null.

const competitions = new Table({
  slug: column.text,
  name: column.text,
  format: column.text,
  legs: column.integer,
  group_count: column.integer,
  advancing: column.integer,
  best_of: column.integer,
  matchday_days: column.integer,
  result_source: column.text,
  status: column.text,
  visibility: column.text,
  allow_late_entry: column.integer,
  require_approval: column.integer,
  max_players: column.integer,
  unplayed_rule: column.text,
  walkover_wins_break_ties: column.integer,
  leave_rule: column.text,
  tie_breaks: column.text,
  starts_at: column.text,
  time_control: column.text,
  early_rounds: column.text,
  points: column.text,
  owner_id: column.text,
  started_at: column.text,
  finished_at: column.text,
  champion_user_id: column.text,
})

const competition_members = new Table({
  competition_id: column.text,
  user_id: column.text,
  joined_at: column.text,
  seed: column.integer,
  group_no: column.integer,
})

const matches = new Table({
  competition_id: column.text,
  round: column.integer,
  leg: column.integer,
  home_user_id: column.text,
  away_user_id: column.text,
  bye_user_id: column.text,
  opens_at: column.text,
  due_at: column.text,
  result: column.text,
  white_user_id: column.text,
  game_url: column.text,
  ended_at: column.text,
  winner_user_id: column.text,
  reminded_at: column.text,
  voided: column.integer,
  note: column.text,
  position: column.integer,
  group_no: column.integer,
  late: column.integer,
  report: column.text,
})

const competition_requests = new Table({
  competition_id: column.text,
  user_id: column.text,
})

const competition_leavers = new Table({
  competition_id: column.text,
  user_id: column.text,
  left_at: column.text,
})

const user = new Table({ name: column.text, image: column.text })

const chess_accounts = new Table({
  user_id: column.text,
  username: column.text,
  avatar: column.text,
})

const notifications = new Table({
  user_id: column.text,
  title: column.text,
  body: column.text,
  url: column.text,
  read_at: column.text,
  created_at: column.text,
})

const game_analyses = new Table({
  user_id: column.text,
  game_url: column.text,
  scores: column.text,
})

export const AppSchema = new Schema({
  competitions,
  competition_members,
  matches,
  competition_requests,
  competition_leavers,
  user,
  chess_accounts,
  notifications,
  game_analyses,
})

export type Database = (typeof AppSchema)['types']
